pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Prefer preserving residual space near the average residual of open bins.
    score += (post - mean).abs() * 1.35;

    // A two-step lookahead is decisive: preserve room for the next item when possible.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= (post - next).min(capacity * 0.75) * 1.25;
        } else {
            score += (next - post) * 1.85;
        }

        // Prefer bins whose leftover can accommodate the next item exactly or
        // with only a small, useful remainder.
        let fit_quality = (post - next).abs() / capacity.max(1.0);
        score += fit_quality * 12.0;
    } else {
        // With no future item known, tightly pack the current bin.
        score += post * 0.32;
    }

    // Avoid creating tiny unusable gaps unless no alternative remains.
    if post > 0.0 && post < item_size.min(next_item_size.max(1)) as f64 {
        score += (item.min(next_item_size.max(1)) as f64 - post) * 1.15;
    }

    // If this is the only currently fitting bin, place the item rather than
    // risk opening another bin; make this preference stronger late in a run.
    if fitting_bins_count == 1 {
        score -= 8.0 + 18.0 * progress;
    }

    // Opening an empty bin is normally competitive only when the current
    // placement leaves substantially more room than the average open bin.
    if bin_residual >= bin_capacity {
        score += 10.0;
        score += (mean - capacity).abs() * 0.08;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slightly favor a bin that was already reasonably well utilized.
    let utilization = 1.0 - (residual / capacity);
    score += (0.50 - utilization) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let item = item_size as f64;
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };

    // Small remnants are much less useful than the raw residual suggests.
    if post_residual == 0 {
        score -= 32.0;
    } else if post_residual < item.min(next_item_size.max(1)) {
        score += 85.0;
    } else if post_residual <= 5 {
        score += 42.0;
    } else if post_residual <= 10 {
        score += 22.0;
    } else if post_residual <= 20 {
        score += 8.0;
    } else {
        score -= (post_residual as f64) * 0.18;
    }

    // Prefer tightly occupied bins, but avoid creating fragmented space.
    score += (post_residual as f64 / capacity) * 14.0;

    // More open bins imply greater pressure to consolidate into existing bins.
    score += (open_bins_count as f64).min(24.0) * 0.75;

    // The final fitting opportunity deserves a stronger consolidation reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // A new bin is useful only when existing residuals are poorly aligned.
    if bin_residual == bin_capacity {
        score += 68.0;
        score += (mean_residual - item).max(0.0) * 0.35;
        if fitting_bins_count > 0 {
            score += 18.0;
        }
    } else {
        // Relative fit quality against the average open-bin residual.
        score -= (mean_residual - post_residual as f64).abs() * 0.06;
    }

    // Near the end of the stream, favor exact closure and avoid tiny gaps.
    if progress > 0.75 {
        if post_residual == 0 {
            score -= 12.0;
        } else if post_residual < item {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_space_threshold = (item_size / 3).max(1) as f64;
    if (post_residual as f64) < dead_space_threshold {
        score += (dead_space_threshold - post_residual as f64) * 18.0;
    }

    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 6.0;
    }

    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 2.5;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.6;

    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Reward preserving enough room for the immediately following item.
    if next_fits {
        score -= 42.0 + 0.20 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize residual space that cannot accommodate the next item.
        score += 24.0 + 0.30 * (next_item_size - post_residual.min(next_item_size)) as f64;
    }

    // Favor residuals near the mean, but strongly reject dead space.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.11 * deviation;
    if post_residual < 10 {
        score += 110.0;
    } else if post_residual < next_item_size && next_item_size > 0 {
        score += 18.0;
    }

    // A new bin is attractive only when it avoids an especially poor fit.
    if is_new_bin {
        score += 32.0;
        if fitting_bins_count == 0 {
            score -= 75.0;
        }
        if progress > 0.80 {
            score -= 8.0;
        }
    } else {
        // Last-chance fitting bins receive a modest preference.
        if fitting_bins_count == 1 {
            score -= 14.0;
        }
        // Prefer using space rather than opening another bin late in the stream.
        if open_bins_count > 1 {
            score -= 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual_before = bin_residual as f64;
    let residual_after = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let utilization = (1.0 - residual_after / capacity).clamp(0.0, 1.0);
    let progress_sq = progress * progress;
    let progress_cube = progress_sq * progress;

    let mut score = residual_after;

    score -= 18.0 * utilization;
    score -= 26.0 * progress * residual_after / capacity;
    score -= 42.0 * progress_sq * residual_after / capacity;
    score -= 15.0 * progress_cube * utilization;
    score -= 0.35 * (residual_after - mean);
    score -= 0.18 * residual_after * mean / capacity;

    if next_item_size > 0 {
        let next = (next_item_size as f64).min(capacity);
        let fit_after = if residual_after + 1e-9 >= next { 1.0 } else { 0.0 };
        score -= 12.0 * fit_after * (0.35 + 0.65 * progress);
        score += 8.0 * progress * (next - residual_after).max(0.0) / capacity;
    }

    if bin_residual == bin_capacity {
        score += 85.0 + 35.0 * progress;
        score -= 8.0 * open_bins_count as f64 * (1.0 - progress);
    }

    if fitting_bins_count == 1 {
        score += 45.0 * (1.0 - progress) + 18.0 * progress;
    }

    score += 0.025 * open_bins_count as f64 * residual_after / capacity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space below the smallest useful item threshold (10) is
    // effectively unusable, so penalize it strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 900.0 + (10.0 - post_residual as f64) * 45.0;
    } else if post_residual == 0 {
        score -= 120.0;
    }

    // Favor exact fills and tight, orderly residuals.
    score -= (post_residual as f64).powi(2) * 0.045;
    score -= (item_size as f64) * 0.35;

    // Look-ahead: avoid leaving a gap just large enough for the next item
    // unless doing so fills this bin completely.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 55.0;
        }
        if post_residual == next_item_size {
            score += 18.0;
        }
        if post_residual >= next_item_size && post_residual <= next_item_size + 5 {
            score -= 28.0;
        }
    }

    // Pressure from many open bins: make consolidation more attractive.
    if open_bins_count > 1 {
        score += (open_bins_count as f64 - 1.0) * 7.0;
    }

    // A final fitting opportunity should be used rather than opening another bin.
    if fitting_bins_count == 1 {
        score -= 160.0;
    }

    // New empty bins are attractive only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 650.0 + mean_residual * 1.2;
    }

    // Mildly favor earlier consolidation, preventing accumulation of bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    let mean = mean_residual.max(0.0);
    let deviation = post_residual as f64 - mean;
    score -= 2.5 * deviation;

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 38.0;
        } else if post_residual >= next_item_size {
            score -= 18.0 + 6.0 * (post_residual - next_item_size) as f64;
        } else {
            let shortfall = (next_item_size - post_residual) as f64;
            score += 10.0 + 4.0 * shortfall;
        }
    } else {
        score -= 0.35 * post_residual as f64;
    }

    let dead_space = item_size as f64 + 1.0;
    if post_residual > 0 && post_residual < item_size {
        score += dead_space + 0.8 * post_residual as f64;
    } else if post_residual == 0 {
        score -= 3.0;
    }

    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score += 12.0;
    }

    if bin_residual == bin_capacity {
        score += 20.0 + 18.0 * progress;
        if next_item_size > 0 && item_size != next_item_size {
            score -= 0.25 * (next_item_size - item_size).abs() as f64;
        }
        score += 4.0 * (open_bins_count as f64).sqrt();
    }

    score -= 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}
